    print(g,sv,w,len(al),len(s),med([r['ttc'] for r in s]),round(m([r['rm'] for r in s]),1))
print("\nby intake")
for ch in ['customer','monitor','partner']:
  for w in ['manual','assist']:
    s=[r for r in D if r['workflow']==w and r['intake_channel']==ch and r['closed']]
    print(ch,w,len(s),med([r['ttc'] for r in s]),round(m([r['rm'] for r in s]),1))
# severity x channel in assist
print(c.Counter((r['workflow'],r['intake_channel'],r['severity']) for r in D))
